import React, { useState, useRef, useEffect } from 'react';
import './GameCanvas.css';

// ==========================================
// Web Audio API Synthesizer Class
// ==========================================
class WebAudioSynth {
  constructor() {
    this.ctx = null;
    this.engineOsc1 = null;
    this.engineOsc2 = null;
    this.engineGain = null;
    this.engineFilter = null;
    this.bgmInterval = null;
    this.isPlayingBGM = false;
    this.isMuted = false;
  }

  init() {
    if (this.ctx) return;
    this.ctx = new (window.AudioContext || window.webkitAudioContext)();
    this.setupEngine();
    this.startBGM();
  }

  setupEngine() {
    if (!this.ctx) return;

    this.engineOsc1 = this.ctx.createOscillator();
    this.engineOsc2 = this.ctx.createOscillator();
    this.engineGain = this.ctx.createGain();
    this.engineFilter = this.ctx.createBiquadFilter();

    // High throttle engine buzz
    this.engineOsc1.type = 'sawtooth';
    this.engineOsc1.frequency.setValueAtTime(55, this.ctx.currentTime); // A1 note base

    // Heavy bass sub rumble
    this.engineOsc2.type = 'triangle';
    this.engineOsc2.frequency.setValueAtTime(27.5, this.ctx.currentTime); // A0 note base

    this.engineFilter.type = 'lowpass';
    this.engineFilter.frequency.setValueAtTime(220, this.ctx.currentTime);

    this.engineGain.gain.setValueAtTime(this.isMuted ? 0 : 0.05, this.ctx.currentTime);

    this.engineOsc1.connect(this.engineFilter);
    this.engineOsc2.connect(this.engineFilter);
    this.engineFilter.connect(this.engineGain);
    this.engineGain.connect(this.ctx.destination);

    this.engineOsc1.start();
    this.engineOsc2.start();
  }

  setEnginePitch(throttleRatio) {
    if (!this.ctx || this.isMuted || !this.engineOsc1) return;
    const now = this.ctx.currentTime;
    // Speed goes from idle (0) to 1.5 (DRS)
    const frequencyMultiplier = 50 + throttleRatio * 90;
    this.engineOsc1.frequency.setTargetAtTime(frequencyMultiplier, now, 0.15);
    this.engineOsc2.frequency.setTargetAtTime(frequencyMultiplier / 2, now, 0.15);
    this.engineFilter.frequency.setTargetAtTime(180 + throttleRatio * 500, now, 0.15);
  }

  playLaser() {
    if (!this.ctx || this.isMuted) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'triangle';
    osc.frequency.setValueAtTime(900, now);
    osc.frequency.exponentialRampToValueAtTime(150, now + 0.15);

    gain.gain.setValueAtTime(0.08, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.15);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start();
    osc.stop(now + 0.15);
  }

  playExplosion() {
    if (!this.ctx || this.isMuted) return;
    const now = this.ctx.currentTime;

    // Create custom noise buffer for crash dispersion
    const bufferSize = this.ctx.sampleRate * 0.4;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = Math.random() * 2 - 1;
    }

    const noise = this.ctx.createBufferSource();
    noise.buffer = buffer;

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(500, now);
    filter.frequency.exponentialRampToValueAtTime(30, now + 0.35);

    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.18, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.4);

    noise.connect(filter);
    filter.connect(gain);
    gain.connect(this.ctx.destination);

    noise.start();
    noise.stop(now + 0.4);
  }

  playPitStop() {
    if (!this.ctx || this.isMuted) return;
    const now = this.ctx.currentTime;
    // pneumatic tyre gun clicks
    for (let i = 0; i < 4; i++) {
      const clickTime = now + i * 0.08;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(400 - i * 50, clickTime);
      gain.gain.setValueAtTime(0.12, clickTime);
      gain.gain.exponentialRampToValueAtTime(0.001, clickTime + 0.05);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start(clickTime);
      osc.stop(clickTime + 0.06);
    }
  }

  playDrsSignal() {
    if (!this.ctx || this.isMuted) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(700, now);
    osc.frequency.setValueAtTime(950, now + 0.08);

    gain.gain.setValueAtTime(0.06, now);
    gain.gain.setValueAtTime(0.06, now + 0.08);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start();
    osc.stop(now + 0.22);
  }

  startBGM() {
    if (this.isPlayingBGM) return;
    this.isPlayingBGM = true;

    let step = 0;
    const stepTime = 0.16; // ~94 BPM 16th feel

    const playBgmStep = () => {
      if (!this.ctx || this.isMuted || !this.isPlayingBGM) return;
      const now = this.ctx.currentTime;

      // Heavy arcade kick
      if (step % 4 === 0) {
        const kick = this.ctx.createOscillator();
        const kickGain = this.ctx.createGain();
        kick.frequency.setValueAtTime(140, now);
        kick.frequency.exponentialRampToValueAtTime(35, now + 0.12);
        kickGain.gain.setValueAtTime(0.08, now);
        kickGain.gain.exponentialRampToValueAtTime(0.001, now + 0.15);
        kick.connect(kickGain);
        kickGain.connect(this.ctx.destination);
        kick.start(now);
        kick.stop(now + 0.15);
      }

      // Synthwave retro arpeggiated bass notes (E, G, A, C)
      const bassNotes = [32.70, 38.89, 43.65, 48.99]; // C1, D#1, F1, G1
      const selectedNote = bassNotes[Math.floor(step / 4) % bassNotes.length];

      const bass = this.ctx.createOscillator();
      const bassFilter = this.ctx.createBiquadFilter();
      const bassGain = this.ctx.createGain();

      bass.type = 'sawtooth';
      bass.frequency.setValueAtTime(selectedNote, now);

      bassFilter.type = 'lowpass';
      bassFilter.frequency.setValueAtTime(140, now);

      bassGain.gain.setValueAtTime(0.02, now);
      bassGain.gain.exponentialRampToValueAtTime(0.001, now + stepTime * 0.9);

      bass.connect(bassFilter);
      bassFilter.connect(bassGain);
      bassGain.connect(this.ctx.destination);

      bass.start(now);
      bass.stop(now + stepTime);

      step = (step + 1) % 16;
    };

    this.bgmInterval = setInterval(playBgmStep, stepTime * 1000);
  }

  stopBGM() {
    this.isPlayingBGM = false;
    if (this.bgmInterval) {
      clearInterval(this.bgmInterval);
      this.bgmInterval = null;
    }
  }

  toggleMute() {
    this.isMuted = !this.isMuted;
    if (this.isMuted) {
      if (this.engineGain) this.engineGain.gain.setValueAtTime(0, this.ctx.currentTime);
    } else {
      if (this.engineGain) this.engineGain.gain.setValueAtTime(0.05, this.ctx.currentTime);
    }
    return this.isMuted;
  }

  destroy() {
    this.stopBGM();
    if (this.ctx) {
      this.ctx.close();
    }
  }
}

// Global synth reference
const synth = new WebAudioSynth();

// ==========================================
// Main React Game Canvas Component
// ==========================================
const GameCanvas = () => {
  const canvasRef = useRef(null);

  // React state for overlays
  const [audioInited, setAudioInited] = useState(false);
  const [gameState, setGameState] = useState('menu'); // menu, playing, pit_stop, level_complete, game_over
  const [selectedTire, setSelectedTire] = useState('medium'); // soft, medium, hard
  const [muteSound, setMuteSound] = useState(false);
  const [ttsEnabled, setTtsEnabled] = useState(true);

  // Teleboard stats (reflected in UI and code)
  const [gameScore, setGameScore] = useState(0);
  const [gameLevel, setGameLevel] = useState(1);
  const [engineerMsg, setEngineerMsg] = useState({ speaker: 'GP', text: 'Welcome to the Red Bull garage. Choose tires and hit Start.' });
  const [scoresList, setScoresList] = useState([]);

  // Telemetry references for standard loops (to avoid React re-renders during 60fps draw)
  const stateRef = useRef({
    gameState: 'menu',
    score: 0,
    level: 1,
    multiplier: 1,
    lastHitTime: 0,
    drsCharge: 0,
    drsActive: false,
    drsTimeLeft: 0,
    tireWear: 100,
    shield: 1,
    tireStrategy: 'medium',
    pitLaneActive: false,
    pitTickerPos: 0,
    pitTickerDir: 1,
    pitSweetSpotStart: 0.35,
    pitSweetSpotEnd: 0.65,
    lastEnemyShot: 0
  });

  // Load High Scores on mount
  useEffect(() => {
    const localScores = JSON.parse(localStorage.getItem('f1_scores') || '[]');
    setScoresList(localScores);
  }, []);

  const handleInitAudio = () => {
    synth.init();
    setAudioInited(true);
    triggerEngineerMessage("Radio check, radio check. Perfect. Ready to start.");
  };

  const triggerEngineerMessage = (text) => {
    setEngineerMsg({ speaker: 'GP', text });
    if (ttsEnabled && window.speechSynthesis) {
      try {
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(text);
        const voices = window.speechSynthesis.getVoices();
        // Look for British accent
        const britishVoice = voices.find(v => v.lang.includes('en-GB') || v.lang.includes('en-US'));
        if (britishVoice) utterance.voice = britishVoice;
        utterance.pitch = 0.9;
        utterance.rate = 1.1;
        utterance.volume = 0.6;
        window.speechSynthesis.speak(utterance);
      } catch (e) {
        console.warn('Speech synthesis failed', e);
      }
    }
  };

  const toggleMuteAudio = () => {
    const isMuted = synth.toggleMute();
    setMuteSound(isMuted);
  };

  // Keyboard control handlers mapped directly to states
  const keys = useRef({});

  const startRace = () => {
    const strategy = selectedTire;
    const baseShield = strategy === 'hard' ? 2 : 1;

    stateRef.current = {
      gameState: 'playing',
      score: 0,
      level: 1,
      multiplier: 1,
      lastHitTime: 0,
      drsCharge: 0,
      drsActive: false,
      drsTimeLeft: 0,
      tireWear: 100,
      shield: baseShield,
      tireStrategy: strategy,
      pitLaneActive: false,
      pitTickerPos: 0.1,
      pitTickerDir: 1.5,
      pitSweetSpotStart: 0.35 + Math.random() * 0.1,
      pitSweetSpotEnd: 0.55 + Math.random() * 0.1,
      lastEnemyShot: Date.now()
    };

    setGameScore(0);
    setGameLevel(1);
    setGameState('playing');
    triggerEngineerMessage(`Push hard now. Strategy is ${strategy.toUpperCase()} tires.`);
  };

  const nextLevel = () => {
    stateRef.current.level += 1;
    setGameLevel(stateRef.current.level);
    stateRef.current.gameState = 'playing';
    setGameState('playing');
    triggerEngineerMessage(`Entering Lap ${stateRef.current.level}. Keep pushing.`);
  };

  // Handle Box action key/click
  const enterPitLane = () => {
    if (stateRef.current.gameState !== 'playing' || stateRef.current.pitLaneActive) return;
    stateRef.current.pitLaneActive = true;
    stateRef.current.pitTickerPos = 0.1;
    stateRef.current.pitSweetSpotStart = 0.3 + Math.random() * 0.15;
    stateRef.current.pitSweetSpotEnd = stateRef.current.pitSweetSpotStart + 0.22;
    synth.playPitStop();
    triggerEngineerMessage("Box box box! Stop on the marks.");
  };

  const triggerPitReaction = () => {
    const s = stateRef.current;
    if (!s.pitLaneActive) return;

    // Check if ticker is in sweet spot
    if (s.pitTickerPos >= s.pitSweetSpotStart && s.pitTickerPos <= s.pitSweetSpotEnd) {
      // Perfect Pit Stop
      s.tireWear = 100;
      s.shield = s.tireStrategy === 'hard' ? 2 : 1;
      s.pitLaneActive = false;
      triggerEngineerMessage("Incredible stop! 1.9 seconds, go, go, go!");
      synth.playLaser();
    } else {
      // Bad Pit Stop - penalty
      triggerEngineerMessage("Sticky wheel nut! Slow stop, 5 seconds... go!");
      s.pitTickerPos = -999; // Disable ticker visual
      setTimeout(() => {
        s.tireWear = 100;
        s.shield = s.tireStrategy === 'hard' ? 2 : 1;
        s.pitLaneActive = false;
      }, 2500);
    }
  };

  // Firing action
  const fireLaser = (player, bullets) => {
    const s = stateRef.current;
    if (s.pitLaneActive) return;

    const bulletSpeed = 9;
    const fireInterval = s.tireStrategy === 'soft' ? 180 : s.tireStrategy === 'medium' ? 260 : 330;
    const now = Date.now();

    if (now - player.lastShot > fireInterval) {
      if (s.drsActive) {
        // Dual barrel firing during DRS
        bullets.push({
          x: player.x + 5,
          y: player.y + 5,
          width: 4,
          height: 12,
          speed: bulletSpeed + 3,
          color: '#00F3FF'
        });
        bullets.push({
          x: player.x + player.width - 9,
          y: player.y + 5,
          width: 4,
          height: 12,
          speed: bulletSpeed + 3,
          color: '#00F3FF'
        });
      } else {
        // Single central laser
        bullets.push({
          x: player.x + player.width / 2 - 2,
          y: player.y - 5,
          width: 4,
          height: 12,
          speed: bulletSpeed,
          color: '#FF0055'
        });
      }
      player.lastShot = now;
      synth.playLaser();
      // shooting degrades tyres slightly
      s.tireWear = Math.max(0, s.tireWear - (s.tireStrategy === 'soft' ? 0.35 : s.tireStrategy === 'medium' ? 0.2 : 0.1));
    }
  };

  // DRS Engage
  const engageDrs = () => {
    const s = stateRef.current;
    if (s.drsCharge >= 100 && !s.drsActive) {
      s.drsActive = true;
      s.drsTimeLeft = 360; // 6 seconds at 60fps
      s.drsCharge = 0;
      synth.playDrsSignal();
      triggerEngineerMessage("DRS enabled, push to overtake!");
    }
  };

  // Main Canvas Rendering Loop
  useEffect(() => {
    if (!audioInited) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    // Resize canvas to full screen
    const handleResize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    // Inputs
    const handleKeyDown = (e) => {
      keys.current[e.code] = true;

      if (e.code === 'Space') {
        e.preventDefault();
        if (stateRef.current.gameState === 'playing') {
          if (stateRef.current.pitLaneActive) {
            triggerPitReaction();
          }
        }
      }
      if (e.code === 'KeyD' && e.shiftKey) {
        engageDrs();
      }
      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engageDrs();
      }
      if (e.code === 'KeyP') {
        enterPitLane();
      }
    };

    const handleKeyUp = (e) => {
      keys.current[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    // Dynamic track offsets
    let trackOffsetY = 0;

    // Objects
    const player = {
      x: canvas.width / 2 - 25,
      y: canvas.height - 180,
      width: 50,
      height: 70,
      speed: 6,
      lastShot: 0
    };

    let enemies = [];
    let bullets = [];
    let enemyBullets = [];
    let particles = [];
    let powerUps = [];

    // Helper: Initialize Enemies
    const initCompetitors = () => {
      enemies = [];
      const s = stateRef.current;
      const rows = 3 + Math.min(s.level, 3);
      const cols = 5 + Math.min(s.level, 4);
      const spacingX = 65;
      const spacingY = 55;
      const trackWidth = canvas.width * 0.7;
      const leftBoundary = (canvas.width - trackWidth) / 2;
      const startX = leftBoundary + (trackWidth - (cols - 1) * spacingX) / 2;
      const startY = 110;

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          // Identify Swerver cars at random
          const isSwerver = r === 0 && Math.random() < 0.35;
          // Level 5 safety car boss
          const isSafetyCar = s.level % 5 === 0 && r === 0 && c === Math.floor(cols / 2);

          enemies.push({
            x: startX + c * spacingX,
            y: startY + r * spacingY,
            width: 44,
            height: 60,
            speed: 1.2 + s.level * 0.3,
            direction: 1,
            isSwerver,
            isSafetyCar,
            health: isSafetyCar ? 8 : 1,
            color: isSafetyCar ? '#FF8800' : isSwerver ? '#FF00CC' : '#FFCC00'
          });
        }
      }
    };

    initCompetitors();

    // Reset loop reference
    stateRef.current.gameState = 'playing';

    // Spark & Exhaust Smoke generator
    const spawnParticle = (x, y, vx, vy, color, life, size = 2) => {
      particles.push({ x, y, vx, vy, color, maxLife: life, life, size });
    };

    let loopId;
    let frameCount = 0;

    // Loop
    const renderLoop = () => {
      frameCount++;
      const s = stateRef.current;

      // Handle Game Complete or Game Over Transitions
      if (s.gameState === 'game_over') {
        setGameState('game_over');
        // Update high scores
        let scores = JSON.parse(localStorage.getItem('f1_scores') || '[]');
        if (!scores.includes(s.score) && s.score > 0) {
          scores.push(s.score);
          scores.sort((a, b) => b - a);
          scores = scores.slice(0, 5);
          localStorage.setItem('f1_scores', JSON.stringify(scores));
          setScoresList(scores);
        }
        synth.stopBGM();
        return;
      }

      if (enemies.length === 0) {
        s.gameState = 'level_complete';
        setGameState('level_complete');
        triggerEngineerMessage(`Checker flag! Lap ${s.level} complete. Fantastic pace.`);
        return;
      }

      // Track Bounds Calculation
      const trackWidth = Math.min(680, canvas.width * 0.85);
      const leftBoundary = (canvas.width - trackWidth) / 2;
      const rightBoundary = leftBoundary + trackWidth;

      // Draw Parallax Race Track Asphalt
      ctx.fillStyle = '#15151e';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = '#1f1f27';
      ctx.fillRect(leftBoundary, 0, trackWidth, canvas.height);

      // Determine speed base on strategy and tire wear
      let speedFactor = 1.0;
      if (s.tireWear <= 30 && s.tireWear > 0) speedFactor = 0.55;
      else if (s.tireWear <= 0) speedFactor = 0.2;

      let playerSpeed = s.tireStrategy === 'soft' ? 7.5 : s.tireStrategy === 'medium' ? 6.2 : 5.0;
      playerSpeed *= speedFactor;
      if (s.drsActive) playerSpeed *= 1.45;

      // Audio engine update
      synth.setEnginePitch(playerSpeed / 7.5);

      // Increment track vertical scrolling
      trackOffsetY += playerSpeed;

      // Draw Curbs (Rumble Strips)
      const curbLen = 50;
      const curbOffset = trackOffsetY % curbLen;
      const segmentsNum = Math.ceil(canvas.height / curbLen) + 1;
      for (let i = -1; i < segmentsNum; i++) {
        const y = i * curbLen + curbOffset;
        const index = Math.floor((trackOffsetY - y) / curbLen);
        const curbColor = (index % 2 === 0) ? '#FF0055' : '#FFFFFF';

        ctx.fillStyle = curbColor;
        // Left
        ctx.fillRect(leftBoundary - 10, y, 10, curbLen);
        // Right
        ctx.fillRect(rightBoundary, y, 10, curbLen);
      }

      // Draw White Track lines
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
      ctx.setLineDash([20, 20]);
      ctx.lineWidth = 3;
      ctx.beginPath();
      // Lane dividers
      ctx.moveTo(leftBoundary + trackWidth * 0.33, 0);
      ctx.lineTo(leftBoundary + trackWidth * 0.33, canvas.height);
      ctx.moveTo(leftBoundary + trackWidth * 0.66, 0);
      ctx.lineTo(leftBoundary + trackWidth * 0.66, canvas.height);
      ctx.stroke();
      ctx.setLineDash([]); // Reset

      // Controls player steer
      if (!s.pitLaneActive) {
        if ((keys.current['ArrowLeft'] || keys.current['KeyA']) && player.x > leftBoundary + 10) {
          player.x -= playerSpeed;
          // Spawn wheel steering dust
          spawnParticle(player.x + 5, player.y + player.height - 10, Math.random() * -1, Math.random() * -1, 'rgba(255, 255, 255, 0.2)', 15, 3);
          s.tireWear = Math.max(0, s.tireWear - 0.05); // scrubbing tires degrades wear
        }
        if ((keys.current['ArrowRight'] || keys.current['KeyD']) && player.x < rightBoundary - player.width - 10) {
          player.x += playerSpeed;
          // Spawn wheel steering dust
          spawnParticle(player.x + player.width - 5, player.y + player.height - 10, Math.random() * 1, Math.random() * -1, 'rgba(255, 255, 255, 0.2)', 15, 3);
          s.tireWear = Math.max(0, s.tireWear - 0.05);
        }

        // Exhaust Fire / Spark emitters
        if (frameCount % 3 === 0) {
          spawnParticle(player.x + player.width / 2, player.y + player.height - 5, (Math.random() - 0.5) * 0.6, 2 + Math.random() * 2, '#FF5500', 20, 2);
          if (playerSpeed > 6) {
            // Spark sparks underneath floor
            spawnParticle(player.x + player.width / 2 + (Math.random() - 0.5) * 15, player.y + player.height - 15, (Math.random() - 0.5) * 2, Math.random() * 1, '#FFAA00', 10, 1.5);
          }
        }

        // Automatic/Manual Firing
        if (keys.current['Space']) {
          fireLaser(player, bullets);
        }
      }

      // Update player tires wear
      s.tireWear = Math.max(0, s.tireWear - (s.tireStrategy === 'soft' ? 0.015 : s.tireStrategy === 'medium' ? 0.007 : 0.003));

      // DRS ticks
      if (s.drsActive) {
        s.drsTimeLeft--;
        if (s.drsTimeLeft <= 0) {
          s.drsActive = false;
          triggerEngineerMessage("DRS disabled, batteries charging.");
        }
        // Emit neon blue aerodynamics trail
        if (frameCount % 2 === 0) {
          spawnParticle(player.x + 5, player.y + 10, 0, 4, '#00F3FF', 25, 2.5);
          spawnParticle(player.x + player.width - 5, player.y + 10, 0, 4, '#00F3FF', 25, 2.5);
        }
      }

      // Update Player Bullets
      bullets = bullets.filter(b => {
        b.y -= b.speed;
        return b.y > 0;
      });

      // Update Enemy Bullets
      enemyBullets = enemyBullets.filter(eb => {
        eb.y += eb.speed;
        return eb.y < canvas.height;
      });

      // Update Competitor Enemies
      let bounceBorder = false;
      enemies.forEach(enemy => {
        if (enemy.isSwerver) {
          // Zig zagging pace
          enemy.x += enemy.speed * enemy.direction * 1.5;
          if (frameCount % 45 === 0 && Math.random() < 0.4) {
            enemy.direction *= -1;
          }
        } else {
          enemy.x += enemy.speed * enemy.direction;
        }

        // Check track borders
        if (enemy.x <= leftBoundary + 10 || enemy.x >= rightBoundary - enemy.width - 10) {
          bounceBorder = true;
        }
      });

      if (bounceBorder) {
        enemies.forEach(enemy => {
          enemy.direction *= -1;
          enemy.y += 24; // descend down track
        });
      }

      // Competitors Shooting loop
      const shotCooldown = Math.max(800, 2000 - s.level * 200);
      if (Date.now() - s.lastEnemyShot > shotCooldown) {
        if (enemies.length > 0) {
          // Select random shooter
          const shooter = enemies[Math.floor(Math.random() * enemies.length)];
          enemyBullets.push({
            x: shooter.x + shooter.width / 2 - 2,
            y: shooter.y + shooter.height - 5,
            width: 4,
            height: 12,
            speed: 4 + s.level * 0.4,
            color: '#FFFF00'
          });
          s.lastEnemyShot = Date.now();
        }
      }

      // Bullet Collisions
      bullets.forEach(bullet => {
        enemies.forEach(enemy => {
          if (
            bullet.x < enemy.x + enemy.width &&
            bullet.x + bullet.width > enemy.x &&
            bullet.y < enemy.y + enemy.height &&
            bullet.y + bullet.height > enemy.y
          ) {
            // Hit enemy
            enemy.health--;
            bullet.dead = true;

            // sparks on hit
            for (let i = 0; i < 6; i++) {
              spawnParticle(bullet.x, bullet.y, (Math.random() - 0.5) * 6, (Math.random() - 0.5) * 6, '#FFFF00', 15);
            }

            if (enemy.health <= 0) {
              enemy.dead = true;
              synth.playExplosion();

              // Big explosion particles
              const particleColor = enemy.isSafetyCar ? '#FF8800' : enemy.isSwerver ? '#FF00CC' : '#FFCC00';
              for (let i = 0; i < 20; i++) {
                spawnParticle(
                  enemy.x + enemy.width / 2,
                  enemy.y + enemy.height / 2,
                  (Math.random() - 0.5) * 8,
                  (Math.random() - 0.5) * 8,
                  particleColor,
                  30,
                  3
                );
              }

              // Combo logic
              const hitNow = Date.now();
              if (hitNow - s.lastHitTime < 2200) {
                s.multiplier = Math.min(10, s.multiplier + 1);
              } else {
                s.multiplier = 1;
              }
              s.lastHitTime = hitNow;

              const pointsGained = (enemy.isSafetyCar ? 1000 : 100) * s.multiplier;
              s.score += pointsGained;
              setGameScore(s.score);

              // Charge DRS
              s.drsCharge = Math.min(100, s.drsCharge + (enemy.isSafetyCar ? 40 : 10));

              // Power-up chance
              if (Math.random() < 0.18) {
                powerUps.push({
                  x: enemy.x + enemy.width / 2 - 8,
                  y: enemy.y + enemy.height / 2,
                  width: 18,
                  height: 18,
                  type: Math.random() < 0.5 ? 'shield' : 'grip',
                  color: '#00F3FF'
                });
              }
            }
          }
        });
      });

      // Filter dead objects
      enemies = enemies.filter(e => !e.dead);
      bullets = bullets.filter(b => !b.dead);

      // Powerups Update and player collection
      powerUps = powerUps.filter(p => {
        p.y += 3; // moves down
        const isColliding =
          p.x < player.x + player.width &&
          p.x + p.width > player.x &&
          p.y < player.y + player.height &&
          p.y + p.height > player.y;

        if (isColliding) {
          if (p.type === 'shield') {
            s.shield = Math.min(3, s.shield + 1);
            triggerEngineerMessage("Shield restored. Aero wing repaired.");
          } else if (p.type === 'grip') {
            s.tireWear = Math.min(100, s.tireWear + 35);
            triggerEngineerMessage("Tires refreshed. Grip is up.");
          }
          synth.playDrsSignal();
          return false;
        }
        return p.y < canvas.height;
      });

      // Enemy Bullets hitting Player
      enemyBullets = enemyBullets.filter(eb => {
        const isColliding =
          eb.x < player.x + player.width &&
          eb.x + eb.width > player.x &&
          eb.y < player.y + player.height &&
          eb.y + eb.height > player.y;

        if (isColliding) {
          s.shield--;
          synth.playExplosion();

          // Flash hit particles
          for (let i = 0; i < 15; i++) {
            spawnParticle(player.x + player.width / 2, player.y + player.height / 2, (Math.random() - 0.5) * 10, (Math.random() - 0.5) * 10, '#FF0055', 20, 2.5);
          }

          if (s.shield <= 0) {
            s.gameState = 'game_over';
            triggerEngineerMessage("We've had a crash, car is retired. Game Over.");
          } else {
            triggerEngineerMessage("Front wing contact! Box soon to replace.");
          }
          return false;
        }
        return true;
      });

      // Check if competitors reached player line or bottom
      const reachedEnd = enemies.some(e => e.y + e.height >= player.y + 10);
      if (reachedEnd) {
        s.gameState = 'game_over';
        triggerEngineerMessage("Compromised line, overtaken. Game Over.");
      }

      // Draw Power-ups
      powerUps.forEach(p => {
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x + p.width / 2, p.y + p.height / 2, p.width / 2, 0, Math.PI * 2);
        ctx.fill();

        // draw overlay icon detail
        ctx.fillStyle = '#020024';
        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(p.type === 'shield' ? 'W' : 'G', p.x + p.width / 2, p.y + p.height / 2 + 3);
      });

      // Draw Competitor F1 Cars (Bezier vector styling)
      enemies.forEach(enemy => {
        const cx = enemy.x;
        const cy = enemy.y;
        const ew = enemy.width;
        const eh = enemy.height;

        // Nose cone and sidepods
        ctx.fillStyle = enemy.color;
        ctx.beginPath();
        ctx.moveTo(cx + ew / 2, cy); // Nose
        ctx.lineTo(cx + ew * 0.75, cy + eh * 0.45); // Right pod
        ctx.lineTo(cx + ew * 0.8, cy + eh * 0.8); // Right board
        ctx.lineTo(cx + ew * 0.2, cy + eh * 0.8); // Left board
        ctx.lineTo(cx + ew * 0.25, cy + eh * 0.45); // Left pod
        ctx.closePath();
        ctx.fill();

        // Front spoiler
        ctx.fillStyle = '#0d0d0d';
        ctx.fillRect(cx + 2, cy + 4, ew - 4, 6);

        // Rear Wing spoiler
        ctx.fillRect(cx + 5, cy + eh - 12, ew - 10, 8);

        // Black tires on corners with wheel spins
        const tireW = 8;
        const tireH = 14;
        ctx.fillStyle = '#111111';
        ctx.fillRect(cx - 3, cy + 8, tireW, tireH); // Front L
        ctx.fillRect(cx + ew - 5, cy + 8, tireW, tireH); // Front R
        ctx.fillRect(cx - 3, cy + eh - 22, tireW, tireH); // Rear L
        ctx.fillRect(cx + ew - 5, cy + eh - 22, tireW, tireH); // Rear R

        // Spin markers inside tires
        ctx.strokeStyle = '#666';
        ctx.lineWidth = 1;
        const tireSpinY = (frameCount * 1.5) % 10;
        ctx.beginPath();
        ctx.moveTo(cx - 3, cy + 8 + tireSpinY);
        ctx.lineTo(cx + 5, cy + 8 + tireSpinY);
        ctx.moveTo(cx + ew - 5, cy + 8 + tireSpinY);
        ctx.lineTo(cx + ew + 3, cy + 8 + tireSpinY);
        ctx.stroke();

        // Safety Car siren details
        if (enemy.isSafetyCar) {
          const sirenColor = frameCount % 10 < 5 ? '#00F3FF' : '#FF0055';
          ctx.fillStyle = sirenColor;
          ctx.beginPath();
          ctx.arc(cx + ew / 2, cy + eh * 0.5, 6, 0, Math.PI * 2);
          ctx.fill();

          // HP indicators
          ctx.fillStyle = '#fff';
          ctx.font = '8px sans-serif';
          ctx.textAlign = 'center';
          ctx.fillText(`SC [${enemy.health}]`, cx + ew / 2, cy - 6);
        }
      });

      // Draw Player Car (Red Bull aerodynamic style)
      const px = player.x;
      const py = player.y;
      const pw = player.width;
      const ph = player.height;

      // Front wing nose
      ctx.fillStyle = '#0600EF'; // Deep blue body
      ctx.beginPath();
      ctx.moveTo(px + pw / 2, py); // Nose tip
      ctx.lineTo(px + pw * 0.8, py + ph * 0.5); // Right board
      ctx.lineTo(px + pw * 0.85, py + ph * 0.85); // Right rear pods
      ctx.lineTo(px + pw * 0.15, py + ph * 0.85); // Left rear pods
      ctx.lineTo(px + pw * 0.2, py + ph * 0.5); // Left board
      ctx.closePath();
      ctx.fill();

      // Yellow airbox details
      ctx.fillStyle = '#FFCC00';
      ctx.beginPath();
      ctx.arc(px + pw / 2, py + ph * 0.4, 4, 0, Math.PI * 2);
      ctx.fill();

      // Front Spoiler
      ctx.fillStyle = '#FF0055'; // Red wing
      ctx.fillRect(px + 4, py + 8, pw - 8, 5);

      // Red Bull Rear spoiler wing (Opens/Moves during DRS)
      ctx.fillStyle = s.drsActive ? '#00F3FF' : '#FF0055';
      const wingFlapHeight = s.drsActive ? 3 : 8;
      ctx.fillRect(px + 6, py + ph - 15, pw - 12, wingFlapHeight);
      if (s.drsActive) {
        // glowing DRS halo on spoiler
        ctx.strokeStyle = '#00F3FF';
        ctx.strokeRect(px + 4, py + ph - 18, pw - 8, 8);
      }

      // Cockpit halo bubble
      ctx.fillStyle = 'rgba(0,0,0,0.85)';
      ctx.beginPath();
      ctx.arc(px + pw / 2, py + ph * 0.55, 5, 0, Math.PI * 2);
      ctx.fill();

      // Spinning Tires
      ctx.fillStyle = '#0b0b0d';
      ctx.fillRect(px - 4, py + 12, 8, 16); // Front L
      ctx.fillRect(px + pw - 4, py + 12, 8, 16); // Front R
      ctx.fillRect(px - 4, py + ph - 28, 8, 16); // Rear L
      ctx.fillRect(px + pw - 4, py + ph - 28, 8, 16); // Rear R

      // spinning lines
      ctx.strokeStyle = '#555';
      ctx.lineWidth = 1;
      const spinOffset = (trackOffsetY) % 10;
      ctx.beginPath();
      ctx.moveTo(px - 4, py + 12 + spinOffset);
      ctx.lineTo(px + 4, py + 12 + spinOffset);
      ctx.moveTo(px + pw - 4, py + 12 + spinOffset);
      ctx.lineTo(px + pw + 4, py + 12 + spinOffset);
      ctx.stroke();

      // Shield active ring
      if (s.shield > 1) {
        ctx.strokeStyle = 'rgba(0, 243, 255, 0.6)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(px + pw / 2, py + ph / 2, Math.max(pw, ph) * 0.6, 0, Math.PI * 2);
        ctx.stroke();
      }

      // Draw Bullets
      bullets.forEach(b => {
        ctx.fillStyle = b.color;
        ctx.fillRect(b.x, b.y, b.width, b.height);
        // tail sparks
        spawnParticle(b.x + b.width / 2, b.y + b.height, (Math.random() - 0.5) * 1, 1, b.color, 8);
      });

      // Draw Enemy Bullets
      enemyBullets.forEach(eb => {
        ctx.fillStyle = eb.color;
        ctx.fillRect(eb.x, eb.y, eb.width, eb.height);
      });

      // Update & Draw Particles
      particles = particles.filter(p => {
        p.x += p.vx;
        p.y += p.vy;
        p.life--;

        ctx.fillStyle = p.color;
        ctx.fillRect(p.x, p.y, p.size, p.size);

        return p.life > 0;
      });

      // ==========================================
      // Draw Telemetry Bottom HUD on Canvas
      // ==========================================
      const hudY = canvas.height - 85;
      const hudHeight = 85;

      // Dark glass background
      ctx.fillStyle = 'rgba(10, 10, 20, 0.9)';
      ctx.fillRect(0, hudY, canvas.width, hudHeight);
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(0, hudY);
      ctx.lineTo(canvas.width, hudY);
      ctx.stroke();

      // Segment HUD locations
      const centerBoxX = canvas.width / 2;

      // Draw Speedometer Dial (Left of center)
      const currentSpeedKmh = Math.floor(playerSpeed * 43);
      ctx.fillStyle = '#ffffff';
      ctx.font = "bold 20px 'Orbitron', sans-serif";
      ctx.textAlign = 'right';
      ctx.fillText(`${currentSpeedKmh}`, centerBoxX - 140, hudY + 38);
      ctx.fillStyle = 'rgba(255,255,255,0.4)';
      ctx.font = "10px 'Orbitron', sans-serif";
      ctx.fillText("KM/H", centerBoxX - 140, hudY + 52);

      // DRS Gauge (Center Area)
      ctx.fillStyle = '#ffffff';
      ctx.font = "9px 'Orbitron', sans-serif";
      ctx.textAlign = 'center';
      ctx.fillText("DRS CHARGE", centerBoxX, hudY + 22);

      // DRS progress track
      const dWidth = 140;
      ctx.fillStyle = 'rgba(255, 255, 255, 0.1)';
      ctx.fillRect(centerBoxX - dWidth / 2, hudY + 28, dWidth, 8);

      // DRS charge fill
      const chargeFill = (s.drsCharge / 100) * dWidth;
      ctx.fillStyle = s.drsCharge >= 100 ? '#00F3FF' : '#FFCC00';
      ctx.fillRect(centerBoxX - dWidth / 2, hudY + 28, chargeFill, 8);

      if (s.drsCharge >= 100) {
        ctx.fillStyle = '#00F3FF';
        ctx.font = "bold 9px 'Orbitron', sans-serif";
        ctx.fillText("DRS READY [SHIFT]", centerBoxX, hudY + 48);
      } else if (s.drsActive) {
        ctx.fillStyle = '#00F3FF';
        ctx.font = "bold 9px 'Orbitron', sans-serif";
        ctx.fillText(`DRS ACTIVE! ${Math.ceil(s.drsTimeLeft / 60)}s`, centerBoxX, hudY + 48);
      }

      // Tire Health Gauge (Right of Center)
      ctx.fillStyle = 'rgba(255,255,255,0.4)';
      ctx.font = "9px 'Orbitron', sans-serif";
      ctx.textAlign = 'left';
      ctx.fillText("TYRE LIFE", centerBoxX + 140, hudY + 22);

      // Tyre wear color
      let tireColor = '#00F3FF';
      if (s.tireWear <= 30) tireColor = '#FF0055';
      else if (s.tireWear <= 60) tireColor = '#FFCC00';

      const tWidth = 100;
      ctx.fillStyle = 'rgba(255, 255, 255, 0.1)';
      ctx.fillRect(centerBoxX + 140, hudY + 28, tWidth, 8);
      ctx.fillStyle = tireColor;
      ctx.fillRect(centerBoxX + 140, hudY + 28, (s.tireWear / 100) * tWidth, 8);

      ctx.fillStyle = '#fff';
      ctx.font = "bold 10px 'Orbitron', sans-serif";
      ctx.fillText(`${Math.round(s.tireWear)}% [${s.tireStrategy.toUpperCase()}]`, centerBoxX + 140, hudY + 48);

      // Low grip warn overlay
      if (s.tireWear <= 30) {
        ctx.fillStyle = '#FF0055';
        ctx.font = "bold 10px 'Orbitron', sans-serif";
        ctx.fillText("BOX NOW! [P]", centerBoxX + 140, hudY + 62);
      }

      // Score / Lap (Far Left HUD)
      ctx.fillStyle = '#fff';
      ctx.font = "14px 'Orbitron', sans-serif";
      ctx.textAlign = 'left';
      ctx.fillText(`Score: ${s.score}`, 30, hudY + 32);
      ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
      ctx.font = "11px 'Orbitron', sans-serif";
      ctx.fillText(`Combo: x${s.multiplier}`, 30, hudY + 50);

      // Shield lights (Far Right HUD)
      ctx.fillStyle = '#fff';
      ctx.font = "11px 'Orbitron', sans-serif";
      ctx.textAlign = 'right';
      ctx.fillText("AERO SHIELD", canvas.width - 30, hudY + 30);
      for (let i = 0; i < 3; i++) {
        ctx.fillStyle = i < s.shield ? '#00F3FF' : 'rgba(255,255,255,0.1)';
        ctx.fillRect(canvas.width - 30 - (3 - i) * 16, hudY + 36, 10, 10);
      }

      // ==========================================
      // Draw Pit Lane reflex timeline if active
      // ==========================================
      if (s.pitLaneActive) {
        // Draw split lane overlay card on Canvas
        const pyX = canvas.width / 2 - 200;
        const pyY = canvas.height / 2 - 80;
        const pyW = 400;
        const pyH = 140;

        ctx.fillStyle = 'rgba(10, 10, 15, 0.92)';
        ctx.fillRect(pyX, pyY, pyW, pyH);
        ctx.strokeStyle = 'rgba(0, 243, 255, 0.4)';
        ctx.strokeRect(pyX, pyY, pyW, pyH);

        ctx.fillStyle = '#fff';
        ctx.font = "bold 14px 'Orbitron', sans-serif";
        ctx.textAlign = 'center';
        ctx.fillText("PIT STOP MECHANICS IN PROGRESS", canvas.width / 2, pyY + 25);
        ctx.fillStyle = 'rgba(255,255,255,0.7)';
        ctx.font = "10px sans-serif";
        ctx.fillText("Hit SPACEBAR when marker enters cyan sweet-spot!", canvas.width / 2, pyY + 45);

        // Timeline Bar
        const barX = pyX + 40;
        const barY = pyY + 70;
        const barW = pyW - 80;
        const barH = 20;

        ctx.fillStyle = 'rgba(255, 255, 255, 0.08)';
        ctx.fillRect(barX, barY, barW, barH);

        // Sweet spot cyan target
        const ssStart = barX + s.pitSweetSpotStart * barW;
        const ssEnd = barX + s.pitSweetSpotEnd * barW;
        ctx.fillStyle = 'rgba(0, 243, 255, 0.4)';
        ctx.fillRect(ssStart, barY, ssEnd - ssStart, barH);
        ctx.strokeStyle = '#00F3FF';
        ctx.strokeRect(ssStart, barY, ssEnd - ssStart, barH);

        // Draw Moving red ticker
        if (s.pitTickerPos !== -999) {
          s.pitTickerPos += 0.015 * s.pitTickerDir;
          if (s.pitTickerPos >= 0.95 || s.pitTickerPos <= 0.05) {
            s.pitTickerDir *= -1; // bounce
          }
          const tickerX = barX + s.pitTickerPos * barW;
          ctx.fillStyle = '#FF0055';
          ctx.fillRect(tickerX - 4, barY - 4, 8, barH + 8);
          ctx.strokeStyle = '#fff';
          ctx.strokeRect(tickerX - 4, barY - 4, 8, barH + 8);
        } else {
          ctx.fillStyle = '#FFCC00';
          ctx.font = "bold 12px 'Orbitron', sans-serif";
          ctx.fillText("PIT DELAY... CLEARING WING DETRITUS", canvas.width / 2, barY + 45);
        }
      }

      loopId = requestAnimationFrame(renderLoop);
    };

    loopId = requestAnimationFrame(renderLoop);

    return () => {
      cancelAnimationFrame(loopId);
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [audioInited, selectedTire, ttsEnabled]);

  // Clean up Web Audio on component unmount
  useEffect(() => {
    return () => {
      synth.destroy();
    };
  }, []);

  return (
    <div className="GameCanvas-container crt screen-flicker">
      <canvas ref={canvasRef} className="GameCanvas-canvas" />

      {/* Audio Setup Prompt */}
      {!audioInited && (
        <div className="audio-init-prompt" onClick={handleInitAudio}>
          <div className="GameCanvas-card">
            <h2 className="GameCanvas-title">F1 Space Invaders</h2>
            <p className="GameCanvas-desc">
              Experience dynamic audio synthesizer humming, pneumatic tyre guns, and the GP Voice Engineer telemetry calls. Click anywhere to activate audio.
            </p>
            <button className="btn-race">Start Audio Setup</button>
          </div>
        </div>
      )}

      {/* Virtual GP Race Engineer Terminal */}
      {audioInited && (
        <div className="engineer-bubble">
          <div className="engineer-avatar">GP</div>
          <div className="engineer-body">
            <span className="engineer-name">Race Engineer</span>
            <span className="engineer-text">{engineerMsg.text}</span>
          </div>
        </div>
      )}

      {/* Dynamic Overlay State Managers */}
      {audioInited && gameState === 'menu' && (
        <div className="GameCanvas-overlay">
          <div className="GameCanvas-card">
            <h1 className="GameCanvas-title">Oracle Red Bull Racing</h1>
            <span className="GameCanvas-subtitle">Arcade Telemetry</span>

            <p className="GameCanvas-desc">
              Select your compound strategy for the sprint race. Soft tires give maximum speed but break down quickly. Hard tires feature a front wing contact shield.
            </p>

            {/* Tire selection cards */}
            <div className="tire-selectors">
              <div 
                className={`tire-card ${selectedTire === 'soft' ? 'selected' : ''}`}
                onClick={() => setSelectedTire('soft')}
              >
                <div className="tire-badge soft">S</div>
                <span className="tire-name">Soft</span>
                <span className="tire-spec">Max Speed</span>
                <span className="tire-spec">Fast Wear</span>
              </div>

              <div 
                className={`tire-card ${selectedTire === 'medium' ? 'selected' : ''}`}
                onClick={() => setSelectedTire('medium')}
              >
                <div className="tire-badge medium">M</div>
                <span className="tire-name">Medium</span>
                <span className="tire-spec">Balanced Pace</span>
                <span className="tire-spec">Med Wear</span>
              </div>

              <div 
                className={`tire-card ${selectedTire === 'hard' ? 'selected' : ''}`}
                onClick={() => setSelectedTire('hard')}
              >
                <div className="tire-badge hard">H</div>
                <span className="tire-name">Hard</span>
                <span className="tire-spec">Slow Pace</span>
                <span className="tire-spec">Wing Shield</span>
              </div>
            </div>

            {/* Start Race */}
            <button className="btn-race" onClick={startRace}>Start Sprint Race</button>

            {/* Settings Toggles */}
            <div style={{ marginTop: '20px', display: 'flex', gap: '15px', fontSize: '11px', color: 'rgba(255,255,255,0.6)' }}>
              <label style={{ cursor: 'pointer' }}>
                <input 
                  type="checkbox" 
                  checked={muteSound} 
                  onChange={toggleMuteAudio} 
                  style={{ marginRight: '5px' }} 
                />
                Mute Audio
              </label>
              <label style={{ cursor: 'pointer' }}>
                <input 
                  type="checkbox" 
                  checked={ttsEnabled} 
                  onChange={(e) => setTtsEnabled(e.target.checked)} 
                  style={{ marginRight: '5px' }} 
                />
                GP Voice Synthesis
              </label>
            </div>

            {/* Controller Instructions */}
            <div className="controls-guide">
              <div className="control-item">
                <span className="key-cap">A / D</span>
                <span>Steering</span>
              </div>
              <div className="control-item">
                <span className="key-cap">Space</span>
                <span>Throttle Shot</span>
              </div>
              <div className="control-item">
                <span className="key-cap">Shift</span>
                <span>DRS Ability</span>
              </div>
              <div className="control-item">
                <span className="key-cap">P</span>
                <span>Box Pitstop</span>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Level Complete Overlay */}
      {audioInited && gameState === 'level_complete' && (
        <div className="GameCanvas-overlay">
          <div className="GameCanvas-card">
            <h1 className="GameCanvas-title" style={{ color: 'var(--neon-blue)' }}>Sprint Finish!</h1>
            <span className="GameCanvas-subtitle">Lap Completed Successfully</span>

            <p className="GameCanvas-desc" style={{ fontSize: '16px' }}>
              Final telemetry score: <strong style={{ color: 'var(--rb-yellow)' }}>{gameScore}</strong>
            </p>

            <button className="btn-race" onClick={nextLevel}>Next Lap {gameLevel + 1}</button>
          </div>
        </div>
      )}

      {/* Game Over Overlay */}
      {audioInited && gameState === 'game_over' && (
        <div className="GameCanvas-overlay">
          <div className="GameCanvas-card">
            <h1 className="GameCanvas-title" style={{ color: 'var(--rb-red)' }}>RETIRED</h1>
            <span className="GameCanvas-subtitle">Sprint Incident</span>

            <p className="GameCanvas-desc" style={{ fontSize: '16px' }}>
              Final Score: <strong style={{ color: 'var(--rb-yellow)' }}>{gameScore}</strong>
            </p>

            {scoresList.length > 0 && (
              <div style={{ width: '100%', marginBottom: '20px' }}>
                <h3 style={{ fontFamily: 'Orbitron', fontSize: '12px', letterSpacing: '1.5px', marginBottom: '5px' }}>TELEMETRY RECORDS</h3>
                <table className="leaderboard-table">
                  <thead>
                    <tr>
                      <th>POS</th>
                      <th>TELEMETRY SCORE</th>
                    </tr>
                  </thead>
                  <tbody>
                    {scoresList.map((sc, index) => (
                      <tr key={index}>
                        <td>{index + 1}</td>
                        <td>{sc}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}

            <button className="btn-race" onClick={() => setGameState('menu')}>Return to Garage</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default GameCanvas;
